PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?person ?label ?birthDate ?abstract WHERE {
  VALUES ?person {
    dbr:Tera_Moody <http://dbpedia.org/resource/Frank_Cignetti,_Jr.>
